"""Decision completeness and resource intervals; no scalar importance authority."""
def assess_unknowns(unknowns):
    """Expose how missing evidence affects an action, without inventing probabilities."""
    required=('unknown','effect_on_recommendation','resolve_with','owner','blocks_commitment')
    for row in unknowns:
        if any(k not in row for k in required):raise ValueError('incomplete uncertainty record')
        if type(row['blocks_commitment']) is not bool:raise ValueError('gate must be explicit')
    return {'unknowns':unknowns,'commitment':'investigate before committing to completion/date' if any(r['blocks_commitment'] for r in unknowns) else 'bounded action can proceed; outcome remains uncertain','confidence':'unquantified; no calibrated probability model','rule':'Prefer a bounded evidence-gathering action when an unresolved input can change the choice; do not equate uncertainty with low impact'}

def duration_days(agent_hours,operator_minutes,agent_hours_per_day,operator_minutes_per_day):
    """Conservative parallel resource bound for a scenario, not a delivery promise."""
    import math
    if agent_hours_per_day<=0 or operator_minutes_per_day<=0:return None
    if not (0<=agent_hours[0]<=agent_hours[1] and 0<=operator_minutes[0]<=operator_minutes[1]):raise ValueError('invalid range')
    return [max(math.ceil(agent_hours[k]/agent_hours_per_day),math.ceil(operator_minutes[k]/operator_minutes_per_day)) for k in (0,1)]
