"""Verify an explicit completion report's evidence, never infer task completion."""
import argparse,hashlib,json
from pathlib import Path
import ledger

def verify(draft,item,artifact):
 if draft.get('item_id')!=item['id']:raise ValueError('wrong work item')
 if type(draft.get('item_revision')) is not int or draft['item_revision']!=item['revision']:raise ValueError('stale work revision')
 if not isinstance(draft.get('claim'),str) or not draft['claim'].strip():raise ValueError('a bounded outcome statement is required')
 if not draft.get('reported_actor'):raise ValueError('reported actor required; this does not authenticate identity')
 expected=draft.get('artifact_sha256');actual=hashlib.sha256(artifact.read_bytes()).hexdigest()
 if expected!=actual:raise ValueError('artifact digest mismatch')
 if draft.get('acceptance_sha256')!=hashlib.sha256(item['acceptance'].encode()).hexdigest():raise ValueError('acceptance changed')
 return {'artifact':{'uri':artifact.resolve().as_uri(),'sha256':actual},'item_id':item['id'],'item_revision':item['revision'],'claim':draft['claim'],'reported_actor':draft['reported_actor'],'checks':[{'id':'work-version-current','status':'pass'},{'id':'artifact-bytes-match','status':'pass'},{'id':'acceptance-satisfied','status':'unknown','detail':'File integrity and a reported action do not establish semantic completion or authenticated human identity'}],'disposition':'evidence integrity verified; outcome review pending'}

def main():
 p=argparse.ArgumentParser();p.add_argument('--draft',type=Path,required=True);p.add_argument('--artifact',type=Path,required=True);p.add_argument('--output',type=Path,required=True);p.add_argument('--record',action='store_true');a=p.parse_args();draft=json.loads(a.draft.read_text());snapshot=ledger.snapshot();item=next((i for i in snapshot['work'] if i['id']==draft.get('item_id')),None)
 if not item:raise ValueError('work item not found')
 result=verify(draft,item,a.artifact)
 if a.record:
  key=ledger.sha(ledger.encode(draft).encode())[:24];doc={'id':'completion-report:'+key,'run_id':'completion-report:'+key,'item_id':item['id'],'attempt':1,'status':'findings','actor':draft['reported_actor'],'recipe_ref':Path(__file__).resolve().as_uri(),'inputs':[result['artifact']],'outputs':[],'checks':result['checks'],'metrics':{'item_revision':item['revision']},'reported_claim':draft['claim']};result['readback']=ledger.record(doc,0)
 a.output.write_text(json.dumps(result,indent=2)+'\n');print(result['disposition'])
if __name__=='__main__':main()
