#!/usr/bin/env python3
"""Unit-explicit stream fan-out arithmetic; no hardware performance claim."""
def budget(bitrate_mbps,viewers,hours,overhead=0.2):
 for name,value in [('bitrate',bitrate_mbps),('viewers',viewers),('hours',hours),('overhead',overhead)]:
