 if not all(math.isfinite(x) for x in (bitrate_mbps,hours,overhead)):raise ValueError('finite inputs required')
 video_gb=bitrate_mbps*1e6/8*hours*3600/1e9
 return {'bitrate_mbps':bitrate_mbps,'viewers':viewers,'hours':hours,'overhead_fraction':overhead,'viewer_egress_mbps':bitrate_mbps*viewers,'budgeted_egress_mbps':bitrate_mbps*viewers*(1+overhead),'viewer_egress_decimal_GB':video_gb*viewers,'budgeted_egress_decimal_GB':video_gb*viewers*(1+overhead),'single_recording_decimal_GB':video_gb,'limits':'No codec-quality, encoder capacity, available uplink, protocol latency or billing guarantee'}
