"""Thin staging adapter: anchored transcript span to a revision-bound edit proposal."""
import hashlib,json
from blake3 import blake3

def sha(text):return hashlib.sha256(text.encode()).hexdigest()
def propose(transcript,segment_id,start,end,target,target_sha,offset,addition,connection):
 if sha(target)!=target_sha:raise ValueError('stale target version')
 if type(offset) is not int or not 0<=offset<=len(target):raise ValueError('invalid target offset')
 segment=next((s for s in transcript['segments'] if s['id']==segment_id),None)
 if segment is None:raise ValueError('missing segment')
 text=segment['text']
 if sha(text)!=segment['text_sha256']:raise ValueError('transcript text digest mismatch')
 if type(start) is not int or type(end) is not int or not 0<=start<end<=len(text):raise ValueError('invalid character span')
 if not 0<=segment['start_ms']<segment['end_ms']<=transcript['duration_ms']:raise ValueError('invalid time anchor')
 media=transcript.get('media',{})
 if not media.get('uri') or not media.get('sha256'):raise ValueError('missing source resource/version')
 quote=text[start:end]
 proposal={'schema_version':1,'status':'proposal','prompt':'unrecorded','source_kind':transcript.get('source_kind','unverified'),'source':media,'segment_id':segment_id,'segment_time_ms':[segment['start_ms'],segment['end_ms']],'quote_span_chars':[start,end],'verbatim_transcript_text':quote,'quote_blake3':blake3(quote.encode()).hexdigest(),'transcript_text_sha256':segment['text_sha256'],'audio_fidelity':'not established by a text hash; exact quote needs source checking','connection':{'kind':'hypothesis','statement':connection,'acceptance':'unreviewed'},'target':{'sha256':target_sha,'insert_at_char':offset},'proposed_addition':addition,'effects':{'target_modified':False,'published':False,'task_reprioritized':False},'handoff':'Existing Descartes/Praxis proposal intake; no receiver admission or public release claimed'}
 proposal['id']='quote-proposal:'+sha(json.dumps(proposal,sort_keys=True,separators=(',',':')))[:24]
 return proposal

def apply_reviewed(proposal,target):
 """Produce candidate bytes only; this is not a filesystem or publication writer."""
 if sha(target)!=proposal['target']['sha256']:raise ValueError('stale target version')
 if proposal.get('status')!='reviewed':raise ValueError('review required before constructing candidate text')
 offset=proposal['target']['insert_at_char'];return target[:offset]+proposal['proposed_addition']+target[offset:]
